/** The identifier of a hold */
export const HoldIdSchema = UuidSchema;

/** The buyer who owns a hold, an order or a ticket */
export const BuyerIdSchema = CallerIdSchema;

/** The state of a hold. A hold starts ACTIVE and moves only to CONVERTED, RELEASED or EXPIRED, which are final */
