/** The hold as it is stored, before the call */
export const StoredHoldSchema = HoldSchema;

/** The unique identifier of one published event message, so that consumers can discard duplicates */
export const MessageIdSchema = UuidSchema;

/** When a published fact occurred, in UTC */
export const OccurredAtSchema = UtcTimeSchema;

/** The published event HoldCreated, a hold was created */
export const HoldCreatedSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, hold_id: HoldIdSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** The answer of a hold request that holds the places, the hold and its HoldCreated */
