/** SECTION_SOLD_OUT, a standing section has not enough capacity left for the requested quantity. The hold holds nothing */
export const SectionSoldOutSchema = v.strictObject({ section: SectionSchema }, 'Must be an object');

/** LIMIT_EXCEEDED, the buyer would hold more than 10 tickets for the event. The hold holds nothing */
export const LimitExceededSchema = v.strictObject({ event_id: EventIdSchema }, 'Must be an object');

/** SALES_CLOSED, the event is not on sale. The hold holds nothing */
export const SalesClosedSchema = v.strictObject({ event_id: EventIdSchema }, 'Must be an object');

/** A request that names one hold, with the hold as stored, when the shell found it */
export const HoldRefSchema = v.pipe(v.strictObject({ hold_id: HoldIdSchema, stored_hold: v.optional(StoredHoldSchema) }, 'Must be an object'),
  $rule("hold_ref", "names_the_hold", "The stored hold is not the hold of the request", (value: any) => ((!((value as any)["stored_hold"] !== undefined)) || $eq(((value as any)["stored_hold"] as any)["hold_id"], (value as any)["hold_id"]))));

/** A call of the shell's clock to expire one hold, with the time of the call and the hold as stored, when the shell found it */
export const ExpiryRequestSchema = v.pipe(v.strictObject({ hold_id: HoldIdSchema, called_at: CalledAtSchema, stored_hold: v.optional(StoredHoldSchema) }, 'Must be an object'),
  $rule("expiry_request", "names_the_hold", "The stored hold is not the hold of the request", (value: any) => ((!((value as any)["stored_hold"] !== undefined)) || $eq(((value as any)["stored_hold"] as any)["hold_id"], (value as any)["hold_id"]))));

/** The state of one hold after a call */
export const HoldStateSchema = v.strictObject({ hold_id: HoldIdSchema, hold_status: HoldStatusSchema }, 'Must be an object');

/** The published event HoldExpired, a hold reached its expiry time without a checkout */
export const HoldExpiredSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, hold_id: HoldIdSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** A hold that expired, with its HoldExpired */
export const ExpiredHoldSchema = v.strictObject({ hold_id: HoldIdSchema, hold_status: HoldStatusSchema, hold_expired: HoldExpiredSchema }, 'Must be an object');

/** HOLD_NOT_FOUND, no hold has this identifier */
export const HoldNotFoundSchema = v.strictObject({ hold_id: HoldIdSchema }, 'Must be an object');

/** HOLD_NOT_ACTIVE, the hold is not ACTIVE, so it cannot be released or expired */
export const HoldNotActiveSchema = v.strictObject({ hold_id: HoldIdSchema, hold_status: HoldStatusSchema }, 'Must be an object');

/** The hold has not reached its expiry time, so it cannot be expired yet */
export const HoldNotDueSchema = v.strictObject({ hold_id: HoldIdSchema, expires_at: ExpiresAtSchema }, 'Must be an object');

/** The reference of the payment that pays for the hold */
export const PaymentReferenceSchema = v.pipe(v.string('Must be a string'),
  $rule("payment_reference", "minLength", "Must have at least 1 characters", (value: any) => (($size(value) as any) >= (1 as any))));

/** The result of the payment for the hold, which the shell gets from the payment provider before the call */
export const PaymentOutcomeSchema = v.pipe(v.string('Must be a string'),
  $rule("payment_outcome", "enum", "Must be one of approved, declined", (value: any) => $in(value, ["approved","declined"])));

/** A request to pay for a hold and turn it into an order, with the result of the payment and the hold as stored, when the shell found it */
export const CheckoutRequestSchema = v.pipe(v.strictObject({ idempotency_key: IdempotencyKeySchema, hold_id: HoldIdSchema, payment_reference: PaymentReferenceSchema, payment_outcome: PaymentOutcomeSchema, caller: CallerSchema, called_at: CalledAtSchema, stored_hold: v.optional(StoredHoldSchema) }, 'Must be an object'),
  $rule("checkout_request", "names_the_hold", "The stored hold is not the hold of the request", (value: any) => ((!((value as any)["stored_hold"] !== undefined)) || $eq(((value as any)["stored_hold"] as any)["hold_id"], (value as any)["hold_id"]))));

/** The code of a ticket, 16 characters from A-Z without I and O, and the digits 2-9 */
export const TicketCodeSchema = v.pipe(v.string('Must be a string'),
  $rule("ticket_code", "pattern", "Must match ^[A-HJ-NP-Z2-9]{16}$", (value: any) => $matches(value, "^[A-HJ-NP-Z2-9]{16}$")));

/** The state of a ticket. ISSUED moves to TRANSFER_PENDING, USED, REFUNDED or VOID; TRANSFER_PENDING moves back to ISSUED; USED, REFUNDED and VOID are final */
export const TicketStatusSchema = v.pipe(v.string('Must be a string'),
  $rule("ticket_status", "enum", "Must be one of ISSUED, TRANSFER_PENDING, USED, REFUNDED, VOID", (value: any) => $in(value, ["ISSUED","TRANSFER_PENDING","USED","REFUNDED","VOID"])));

/** A ticket for one seat or one standing place of an event, owned by a buyer */
