/** The order as it is stored, before the call */
export const StoredOrderSchema = OrderSchema;

/** Ticket codes, each one time */
export const TicketCodesSchema = v.pipe(v.array(TicketCodeSchema, 'Must be a list'),
  $rule("ticket_codes", "minItems", "Must have at least 1 items", (value: any) => (($size(value) as any) >= (1 as any))),
  $rule("ticket_codes", "maxItems", "Must have at most 10 items", (value: any) => (($size(value) as any) <= (10 as any))),
  $rule("ticket_codes", "uniqueItems", "Must not have an item two times", (value: any) => (value as any[]).every((v_x: any) => ((value as any[]).filter((v_y: any) => $eq(v_y, v_x)).length === 1))));

/** The published event OrderPlaced, an order was placed and paid */
export const OrderPlacedSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, order_id: OrderIdSchema, hold_id: HoldIdSchema, ticket_codes: TicketCodesSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** The published event TicketIssued, a ticket was issued */
export const TicketIssuedSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, ticket_code: TicketCodeSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** The TicketIssued events of an order, one per ticket */
export const TicketsIssuedSchema = v.array(TicketIssuedSchema, 'Must be a list');

/** The hold that an order pays for, now CONVERTED */
export const ConvertedHoldSchema = HoldStateSchema;

/** The answer of a checkout that pays, the order, the hold that it converts, its OrderPlaced and a TicketIssued per ticket */
export const PlacedOrderSchema = v.strictObject({ order: OrderSchema, converted_hold: ConvertedHoldSchema, order_placed: OrderPlacedSchema, tickets_issued: TicketsIssuedSchema }, 'Must be an object');

/** HOLD_EXPIRED, the checkout came after the expiry time of the hold, or the hold is no longer ACTIVE. No ticket is issued */
export const HoldExpiredRefusalSchema = v.strictObject({ hold_id: HoldIdSchema, expires_at: ExpiresAtSchema }, 'Must be an object');

/** PAYMENT_DECLINED, the payment failed. No ticket is issued */
export const PaymentDeclinedSchema = v.strictObject({ payment_reference: PaymentReferenceSchema }, 'Must be an object');

/** FORBIDDEN, the caller may not do this */
export const ForbiddenSchema = v.strictObject({ caller_id: CallerIdSchema }, 'Must be an object');

/** A request that names one order, with the order as stored, when the shell found it */
export const OrderRefSchema = v.pipe(v.strictObject({ order_id: OrderIdSchema, stored_order: v.optional(StoredOrderSchema) }, 'Must be an object'),
  $rule("order_ref", "names_the_order", "The stored order is not the order of the request", (value: any) => ((!((value as any)["stored_order"] !== undefined)) || $eq(((value as any)["stored_order"] as any)["order_id"], (value as any)["order_id"]))));

/** ORDER_NOT_FOUND, no order has this identifier */
export const OrderNotFoundSchema = v.strictObject({ order_id: OrderIdSchema }, 'Must be an object');

/** The email address of the person who receives a transferred ticket */
export const RecipientEmailSchema = EmailSchema;

/** A request to transfer one ticket to a recipient, with the ticket and its event as stored, when the shell found the ticket */
export const TransferRequestSchema = v.pipe(v.strictObject({ ticket_code: TicketCodeSchema, recipient_email: RecipientEmailSchema, caller: CallerSchema, called_at: CalledAtSchema, stored_ticket: v.optional(StoredTicketSchema), show: v.optional(ShowSchema) }, 'Must be an object'),
  $rule("transfer_request", "names_the_ticket", "The stored ticket is not the ticket of the request", (value: any) => ((!((value as any)["stored_ticket"] !== undefined)) || $eq(((value as any)["stored_ticket"] as any)["ticket_code"], (value as any)["ticket_code"]))),
  $rule("transfer_request", "show_of_the_ticket", "The stored event is not the event of the ticket", (value: any) => ((!((value as any)["stored_ticket"] !== undefined)) || (((value as any)["show"] !== undefined) && $eq(((value as any)["show"] as any)["event_id"], ((value as any)["stored_ticket"] as any)["event_id"])))));

/** The identifier of a transfer */
export const TransferIdSchema = UuidSchema;

/** When a transfer was offered, in UTC */
export const OfferedAtSchema = UtcTimeSchema;

/** The last time the recipient can accept a transfer, in UTC, 72 hours after the offer */
export const AcceptUntilSchema = UtcTimeSchema;

/** A transfer of one ticket that waits for the recipient */
export const TransferSchema = v.pipe(v.strictObject({ transfer_id: TransferIdSchema, ticket_code: TicketCodeSchema, recipient_email: RecipientEmailSchema, offered_at: OfferedAtSchema, accept_until: AcceptUntilSchema }, 'Must be an object'),
  $rule("transfer", "accept_after_offer", "The end of the acceptance window must be after the offer", (value: any) => (($timestamp((value as any)["accept_until"]) as any) > ($timestamp((value as any)["offered_at"]) as any))));

