export const StoredTransferSchema = TransferSchema;

/** The state of one ticket after a call */
export const TicketStateSchema = v.strictObject({ ticket_code: TicketCodeSchema, ticket_status: TicketStatusSchema }, 'Must be an object');

/** The ticket of a transfer, now TRANSFER_PENDING */
export const PendingTicketSchema = TicketStateSchema;

/** The answer of a transfer request, the transfer and its ticket, now TRANSFER_PENDING */
export const OfferedTransferSchema = v.strictObject({ transfer: TransferSchema, pending_ticket: PendingTicketSchema }, 'Must be an object');

/** TICKET_NOT_FOUND, no ticket has this code */
export const TicketNotFoundSchema = v.strictObject({ ticket_code: TicketCodeSchema }, 'Must be an object');

/** INVALID_TICKET_STATE, the ticket is not in a state that allows this */
export const InvalidTicketStateSchema = v.strictObject({ ticket_code: TicketCodeSchema, ticket_status: TicketStatusSchema }, 'Must be an object');

/** TRANSFER_WINDOW_CLOSED, the event starts in 2 hours or less, so its tickets can no longer be transferred */
export const TransferWindowClosedSchema = v.strictObject({ ticket_code: TicketCodeSchema, starts_at: StartsAtSchema }, 'Must be an object');

/** A request of the recipient to accept a transfer, with the transfer, its ticket and the ticket's event as stored, when the shell found the transfer */
export const AcceptanceSchema = v.pipe(v.strictObject({ transfer_id: TransferIdSchema, caller: CallerSchema, called_at: CalledAtSchema, stored_transfer: v.optional(StoredTransferSchema), stored_ticket: v.optional(StoredTicketSchema), show: v.optional(ShowSchema) }, 'Must be an object'),
  $rule("acceptance", "names_the_transfer", "The stored transfer is not the transfer of the request", (value: any) => ((!((value as any)["stored_transfer"] !== undefined)) || $eq(((value as any)["stored_transfer"] as any)["transfer_id"], (value as any)["transfer_id"]))),
  $rule("acceptance", "ticket_of_the_transfer", "The stored ticket is not the ticket of the transfer", (value: any) => ((!((value as any)["stored_transfer"] !== undefined)) || (((value as any)["stored_ticket"] !== undefined) && $eq(((value as any)["stored_ticket"] as any)["ticket_code"], ((value as any)["stored_transfer"] as any)["ticket_code"])))),
  $rule("acceptance", "show_of_the_ticket", "The stored event is not the event of the ticket", (value: any) => ((!((value as any)["stored_ticket"] !== undefined)) || (((value as any)["show"] !== undefined) && $eq(((value as any)["show"] as any)["event_id"], ((value as any)["stored_ticket"] as any)["event_id"])))));

/** The new ticket of the recipient of a transfer */
