/** The code of the ticket that a transfer made VOID */
export const VoidTicketCodeSchema = TicketCodeSchema;

/** The published event TicketTransferred, a transfer was accepted. The old ticket code is VOID and the recipient has a new ticket code for the same place */
export const TicketTransferredSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, ticket_code: TicketCodeSchema, void_ticket_code: VoidTicketCodeSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** The answer of an accepted transfer, the recipient's new ticket, the old ticket now VOID, and its TicketTransferred */
export const AcceptedTransferSchema = v.strictObject({ new_ticket: NewTicketSchema, void_ticket: VoidTicketSchema, ticket_transferred: TicketTransferredSchema }, 'Must be an object');

/** TRANSFER_NOT_FOUND, no transfer has this identifier */
export const TransferNotFoundSchema = v.strictObject({ transfer_id: TransferIdSchema }, 'Must be an object');

/** TRANSFER_EXPIRED, the transfer was offered more than 72 hours ago, so the recipient can no longer accept it */
export const TransferExpiredSchema = v.strictObject({ transfer_id: TransferIdSchema, accept_until: AcceptUntilSchema }, 'Must be an object');

/** A request that names one transfer, with the transfer and its ticket as stored, when the shell found the transfer */
export const TransferRefSchema = v.pipe(v.strictObject({ transfer_id: TransferIdSchema, stored_transfer: v.optional(StoredTransferSchema), stored_ticket: v.optional(StoredTicketSchema) }, 'Must be an object'),
  $rule("transfer_ref", "names_the_transfer", "The stored transfer is not the transfer of the request", (value: any) => ((!((value as any)["stored_transfer"] !== undefined)) || $eq(((value as any)["stored_transfer"] as any)["transfer_id"], (value as any)["transfer_id"]))),
  $rule("transfer_ref", "ticket_of_the_transfer", "The stored ticket is not the ticket of the transfer", (value: any) => ((!((value as any)["stored_transfer"] !== undefined)) || (((value as any)["stored_ticket"] !== undefined) && $eq(((value as any)["stored_ticket"] as any)["ticket_code"], ((value as any)["stored_transfer"] as any)["ticket_code"])))));

/** A request of a buyer to refund tickets of an order, with the order, the requested tickets and the event as stored, when the shell found the order */
export const RefundRequestSchema = v.pipe(v.strictObject({ idempotency_key: IdempotencyKeySchema, order_id: OrderIdSchema, ticket_codes: TicketCodesSchema, caller: CallerSchema, called_at: CalledAtSchema, stored_order: v.optional(StoredOrderSchema), stored_tickets: v.optional(StoredTicketsSchema), show: v.optional(ShowSchema) }, 'Must be an object'),
  $rule("refund_request", "names_the_order", "The stored order is not the order of the request", (value: any) => ((!((value as any)["stored_order"] !== undefined)) || $eq(((value as any)["stored_order"] as any)["order_id"], (value as any)["order_id"]))),
  $rule("refund_request", "loads_the_requested_tickets", "The stored tickets are not the requested tickets of the order", (value: any) => ((!((value as any)["stored_order"] !== undefined)) || ((((value as any)["stored_tickets"] !== undefined) && $eq($size((value as any)["stored_tickets"]), $size((value as any)["ticket_codes"]))) && ((value as any)["ticket_codes"] as any[]).every((v_c: any) => ((((value as any)["stored_tickets"] as any[]).filter((v_t: any) => $eq((v_t as any)["ticket_code"], v_c)).length === 1) && (((value as any)["stored_order"] as any)["tickets"] as any[]).some((v_t: any) => $eq((v_t as any)["ticket_code"], v_c))))))),
  $rule("refund_request", "show_of_the_order", "The stored event is not the event of the order", (value: any) => ((!((value as any)["stored_order"] !== undefined)) || (((value as any)["show"] !== undefined) && $eq(((value as any)["show"] as any)["event_id"], ((value as any)["stored_order"] as any)["event_id"])))));

/** The identifier of a refund */
export const RefundIdSchema = UuidSchema;

/** A refund of tickets of an order */
export const RefundSchema = v.strictObject({ refund_id: RefundIdSchema, order_id: OrderIdSchema, ticket_codes: TicketCodesSchema, refund_amount: RefundAmountSchema }, 'Must be an object');

/** The published event TicketRefunded, a ticket was refunded */
export const TicketRefundedSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, ticket_code: TicketCodeSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** The TicketRefunded events of a call, one per refunded ticket */
export const TicketsRefundedSchema = v.array(TicketRefundedSchema, 'Must be a list');

/** The tickets that a call refunds, each now REFUNDED */
export const RefundedTicketsSchema = v.array(TicketStateSchema, 'Must be a list');

/** The answer of a refund request that refunds, the refund, its tickets now REFUNDED, and a TicketRefunded per ticket */
export const GrantedRefundSchema = v.strictObject({ refund: RefundSchema, refunded_tickets: RefundedTicketsSchema, tickets_refunded: TicketsRefundedSchema }, 'Must be an object');

/** TICKET_NOT_REFUNDABLE, the ticket is USED, REFUNDED or VOID, so it cannot be refunded */
export const TicketNotRefundableSchema = v.strictObject({ ticket_code: TicketCodeSchema }, 'Must be an object');

/** REFUND_WINDOW_CLOSED, the event starts in 48 hours or less, so the buyer can no longer refund tickets of the order */
export const RefundWindowClosedSchema = v.strictObject({ order_id: OrderIdSchema, starts_at: StartsAtSchema }, 'Must be an object');

/** A ticket presented at the entry of an event, with the member of staff who scans it and the ticket as stored, when the shell found it */
export const EntryScanSchema = v.pipe(v.strictObject({ ticket_code: TicketCodeSchema, event_id: EventIdSchema, caller: CallerSchema, called_at: CalledAtSchema, stored_ticket: v.optional(StoredTicketSchema) }, 'Must be an object'),
  $rule("entry_scan", "names_the_ticket", "The stored ticket is not the ticket of the request", (value: any) => ((!((value as any)["stored_ticket"] !== undefined)) || $eq(((value as any)["stored_ticket"] as any)["ticket_code"], (value as any)["ticket_code"]))));

/** The answer to a ticket at the entry of an event */
export const VerdictSchema = v.pipe(v.string('Must be a string'),
  $rule("verdict", "enum", "Must be one of ADMIT, ALREADY_USED, NOT_VALID, WRONG_EVENT", (value: any) => $in(value, ["ADMIT","ALREADY_USED","NOT_VALID","WRONG_EVENT"])));

/** The published event TicketUsed, a ticket was admitted at the entry */
export const TicketUsedSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, ticket_code: TicketCodeSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** The ticket that the entry admitted, now USED */
export const UsedTicketSchema = TicketStateSchema;

/** The answer to a ticket presented at the entry; when it admits the ticket, the ticket now USED and its TicketUsed */
export const EntryResultSchema = v.strictObject({ ticket_code: TicketCodeSchema, event_id: EventIdSchema, verdict: VerdictSchema, used_ticket: v.optional(UsedTicketSchema), ticket_used: v.optional(TicketUsedSchema) }, 'Must be an object');

/** A request of an organizer to cancel an event, with the event and its tickets as stored */
export const EventCancellationSchema = v.pipe(v.strictObject({ event_id: EventIdSchema, caller: CallerSchema, called_at: CalledAtSchema, show: ShowSchema, stored_tickets: StoredTicketsSchema }, 'Must be an object'),
  $rule("event_cancellation", "names_the_show", "The stored event is not the event of the request", (value: any) => $eq(((value as any)["show"] as any)["event_id"], (value as any)["event_id"])),
  $rule("event_cancellation", "tickets_of_the_show", "A stored ticket is of another event", (value: any) => ((value as any)["stored_tickets"] as any[]).every((v_t: any) => $eq((v_t as any)["event_id"], (value as any)["event_id"]))));

/** When the organizer cancelled an event, in UTC */
export const CancelledAtSchema = UtcTimeSchema;

/** The codes of the tickets that a cancellation refunds */
export const AffectedTicketsSchema = v.pipe(v.array(TicketCodeSchema, 'Must be a list'),
  $rule("affected_tickets", "uniqueItems", "Must not have an item two times", (value: any) => (value as any[]).every((v_x: any) => ((value as any[]).filter((v_y: any) => $eq(v_y, v_x)).length === 1))));

/** The published event EventCancelled, the organizer cancelled an event, with the tickets it refunds */
export const EventCancelledSchema = v.strictObject({ message_id: MessageIdSchema, event_id: EventIdSchema, affected_tickets: AffectedTicketsSchema, occurred_at: OccurredAtSchema }, 'Must be an object');

/** An event that the organizer cancelled, with its EventCancelled, its ISSUED or TRANSFER_PENDING tickets now REFUNDED, and a TicketRefunded per such ticket */
export const CancelledEventSchema = v.strictObject({ event_id: EventIdSchema, cancelled_at: CancelledAtSchema, event_cancelled: EventCancelledSchema, refunded_tickets: RefundedTicketsSchema, tickets_refunded: TicketsRefundedSchema }, 'Must be an object');

